/* ---------- Step library ---------- */
/* the steps a workflow can be built from, in a side panel beside the workflow: a search, groups that fold, and a row per
   step. Hovering or focusing a step shows what it does in a card beside the panel, never over the list; Enter, a click or
   a drag into the workflow adds it. On a narrow screen the workflow steps aside and the description shows at the foot of
   the panel instead */
.slb{position:relative;width:100%;height:400px;display:flex;gap:var(--s-4);container:slb/inline-size;--slb-wire:var(--field-line)}
.slb-p{position:relative;z-index:1;width:256px;flex:none;display:flex;flex-direction:column;min-height:0;border-radius:var(--r-card);background:var(--surface);box-shadow:var(--shadow)}
.slb-h{display:flex;align-items:baseline;justify-content:space-between;gap:var(--s-2);padding:var(--s-3) var(--s-4) 0;font-size:13px}
.slb-h b{font-weight:500}
.slb-h .num{font-size:12px;color:var(--muted)}
.slb-q{display:flex;align-items:center;gap:var(--s-2);height:32px;margin:var(--s-2) var(--s-3) var(--s-1);padding:0 var(--s-1) 0 var(--s-3);border-radius:var(--r-sm);background:var(--chip);box-shadow:inset 0 0 0 1px var(--field-line);color:var(--muted)}
.slb-q:focus-within{box-shadow:inset 0 0 0 2px var(--focus)}
.slb-q input{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--fg)}
.slb-q input::placeholder{color:var(--muted)}
.slb-x{width:24px;height:24px}
.slb-list{flex:1;min-height:0;overflow-y:auto;padding:var(--s-1) var(--s-2) var(--s-2);scrollbar-width:thin;scrollbar-color:var(--rail) transparent}
.slb-g+.slb-g{margin-top:var(--s-1)}
.slb-g[hidden]{display:none}
.slb-gb{display:flex;align-items:center;gap:var(--s-2);width:100%;height:28px;padding:0 var(--s-2);border-radius:var(--r-sm);font-size:12px;color:var(--fg2);text-align:left;transition:background var(--t-fast),color var(--t-fast)}
@media (hover:hover) and (pointer:fine){.slb-gb:hover{background:var(--row);color:var(--fg)}}
.slb-gb:focus-visible,.slb-s:focus-visible{outline-offset:-2px}
.slb-gb .i{color:var(--muted);transition:transform var(--t) var(--ease)}
.slb-gb[aria-expanded="false"] .i{transform:rotate(-90deg)}
.slb-gb .n{margin-left:auto;color:var(--muted)}
.slb-ul{list-style:none;margin:0;padding:0}
.slb-s{display:flex;align-items:center;gap:var(--s-2);width:100%;height:36px;padding:0 var(--s-2);border-radius:var(--r-sm);font-size:13px;text-align:left;color:var(--fg);transition:background var(--t-fast)}
.slb-s.on{background:var(--row)}
@media (hover:hover) and (pointer:fine){.slb-s:hover{background:var(--row)}}
.slb-s .ic{width:24px;height:24px;border-radius:var(--r-sm);display:grid;place-items:center;flex:none}
.slb-s .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.slb-s mark{background:none;color:var(--accent-fg);font-weight:500}
.slb-s .ad{display:grid;color:var(--muted);opacity:0;transition:opacity var(--t-fast),color var(--t-fast)}
@media (hover:hover) and (pointer:fine){.slb-s:is(:hover,:focus-visible,.on) .ad{opacity:1}}
.slb-s.added .ad{opacity:1;color:var(--ok)}
.slb-e{display:flex;flex-direction:column;align-items:center;gap:var(--s-1);padding:var(--s-8) var(--s-4) 0;text-align:center;font-size:13px;color:var(--muted)}
.slb-e b{font-weight:500;color:var(--fg);overflow-wrap:anywhere}
.slb-e .pill{margin-top:var(--s-2)}
.slb-dock{display:none}
.slb-d{display:none}
/* the workflow the steps go into: a quiet canvas with its steps one under another, and a place to drop a new one */
.slb-flow{position:relative;flex:1;min-width:0;display:flex;flex-direction:column;padding:var(--s-4) var(--s-5);border-radius:var(--r-lg);
  background-color:var(--chip);background-image:radial-gradient(circle at 8px 8px,color-mix(in srgb,var(--fg) 16%,transparent) 1.1px,transparent 1.6px);background-size:16px 16px;transition:box-shadow var(--t-fast)}
.slb-fh{display:flex;align-items:baseline;gap:var(--s-2);font-size:13px}
.slb-fh b{font-weight:500}
.slb-fh .num{font-size:12px;color:var(--fg2)}
.slb-fl{list-style:none;flex:1;min-height:0;margin:0;padding:var(--s-4) 0 var(--s-1);display:flex;flex-direction:column;gap:var(--s-4);overflow-y:auto;scrollbar-width:none}
.slb-fs{position:relative;display:flex;align-items:center;gap:var(--s-3);font-size:13px}
.slb-fs.in{animation:slbin .5s var(--ease) backwards}
@keyframes slbin{from{opacity:0;transform:translateY(6px);filter:blur(3px)}}
.slb-fs .ic{width:32px;height:32px;border-radius:var(--r-sm);display:grid;place-items:center;flex:none;background:var(--surface);box-shadow:var(--shadow)}
.slb-fs .t{display:flex;flex-direction:column;min-width:0;line-height:1.3}
.slb-fs .t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.slb-fs .t span{font-size:12px;color:var(--fg2)}
/* the line from one step down to the next, under its icon */
.slb-cn{position:absolute;left:15.5px;top:32px;bottom:calc(var(--s-4) * -1);width:1px;background:var(--slb-wire)}
.slb-fs:last-child .slb-cn{display:none}
.slb-drop{flex:none;display:flex;align-items:center;gap:var(--s-2);height:40px;padding:0 var(--s-3);border-radius:var(--r-sm);box-shadow:inset 0 0 0 1px var(--field-line);font-size:12.5px;color:var(--fg2);transition:background var(--t-fast),color var(--t-fast),box-shadow var(--t-fast)}
.slb-flow.over .slb-drop{background:var(--accent-bg);color:var(--accent-fg);box-shadow:inset 0 0 0 2px var(--accent-mark)}
/* the preview: beside the panel, level with the step it describes, over the workflow and never over the list */
.slb-pv{position:absolute;left:0;top:0;z-index:5;width:232px;padding:var(--s-3);border-radius:var(--r-in);background:var(--raised);box-shadow:var(--shadow-pop);pointer-events:none;
  opacity:0;visibility:hidden;transform:translateX(-4px);transition:opacity .18s var(--ease),transform .3s var(--ease),top .25s var(--ease),visibility 0s .3s}
.slb-pv.show{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.slb-pv.jump{transition:opacity .18s var(--ease),transform .3s var(--ease),visibility 0s .3s}
.slb-ph{display:flex;align-items:center;gap:var(--s-2)}
.slb-ph .ic{width:28px;height:28px;border-radius:var(--r-sm);display:grid;place-items:center;flex:none}
.slb-ph div{display:flex;flex-direction:column;min-width:0}
.slb-ph b{font-weight:500;font-size:13px}
.slb-ph span{font-size:12px;color:var(--fg2)}
.slb-pd{margin:var(--s-2) 0 0;font-size:12.5px;line-height:1.5;color:var(--fg)}
.slb-io{margin:var(--s-2) 0 0;display:grid;grid-template-columns:auto minmax(0,1fr);gap:0 var(--s-2);font-size:12px;line-height:1.45}
.slb-io dt{color:var(--fg2)}
.slb-io dd{margin:0;color:var(--fg)}
.slb-pf{margin:var(--s-2) 0 0;font-size:12px;color:var(--fg2)}
.slb-live{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* narrow: the panel takes the width, and what the focused or hovered step does shows at its foot */
@container slb (max-width:559px){
  .slb-flow,.slb-pv{display:none}
  .slb-p{width:100%}
  .slb-dock{display:block;flex:none;height:92px;padding:var(--s-3) var(--s-4);box-shadow:inset 0 1px 0 var(--line);overflow:hidden}
  .slb-dock .slb-pd{margin-top:var(--s-1);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  .slb-dock .hint{font-size:12.5px;color:var(--fg2)}
}
:root:not([data-style="soft"]) .slb-q:not(:where([data-style="soft"],[data-style="soft"] *)){background:var(--surface)}
:root:not([data-style="soft"]) .slb-flow:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px var(--line)}
:root:not([data-style="soft"]) .slb-fs .ic:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:0 0 0 1px var(--rail)}

DM.def('step-library', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{(search|x|plus)\}/g, (m, n) => I(n));
  // the steps, by group: an id, an icon, the name, what it does, what it takes and what it gives
  const G = [
    { id:'ai', l:'AI', col:'var(--accent-mark,var(--accent))', fg:'var(--accent-fg,var(--accent))', s:[
      ['summarize', 'spark', 'Summarize text', 'Turns long text into a short summary or a few bullet points, at the length you set.', 'Any text, like a thread or a transcript', 'A summary'],
      ['classify', 'hash', 'Classify', 'Sorts what comes in into one of the labels you list, with how sure it is.', 'Text and your labels', 'A label and a score'],
      ['extract', 'table', 'Extract fields', 'Pulls named fields, like a date or an order number, out of free text.', 'Text and the fields to find', 'A record with those fields'],
      ['draft', 'edit', 'Write a draft', 'Writes a first draft from your instructions and what the earlier steps found.', 'Instructions and context', 'Draft text to review'] ] },
    { id:'tools', l:'Tools', col:'var(--pb)', s:[
      ['web', 'globe', 'Search the web', 'Runs a web search and passes on the top results with their links.', 'A query', 'Results with titles and links'],
      ['file', 'file-text', 'Read a file', 'Opens a document from the workspace and passes on its text.', 'A file', 'The text of the file'],
      ['db', 'db', 'Query a database', 'Runs a read-only query and returns the rows that match.', 'A query', 'Rows as a table'],
      ['api', 'link', 'Call an API', 'Sends an HTTP request and hands the response to the next step.', 'A URL, a method and a body', 'The response'] ] },
    { id:'logic', l:'Logic', col:'var(--pl)', s:[
      ['if', 'branch', 'If / else', 'Sends the run down one of two paths, depending on a condition.', 'A condition', 'One of two paths'],
      ['loop', 'refresh', 'Loop over items', 'Runs the steps inside it once for each item in a list.', 'A list', 'One result per item'],
      ['wait', 'clock', 'Wait', 'Pauses the run for a set time, or until a date and time.', 'A duration or a date', 'The run, later'],
      ['approve', 'shield', 'Ask for approval', 'Holds the run until a person approves or rejects what happens next.', 'Who to ask, and what', 'Approved or rejected'] ] },
    { id:'actions', l:'Actions', col:'var(--pm)', s:[
      ['email', 'mail', 'Send an email', 'Sends an email from your workspace to one or more people.', 'To, subject and body', 'The sent email'],
      ['post', 'send', 'Post a message', 'Posts a message in a team chat channel.', 'A channel and the message', 'The posted message'],
      ['ticket', 'flag', 'Create a ticket', 'Opens a ticket in your tracker with a title, details and an owner.', 'Title, details and owner', 'The new ticket'],
      ['record', 'sliders', 'Update a record', 'Changes fields on a record in your CRM or database.', 'The record and its new values', 'The updated record'] ] }
  ];
  G.forEach(g => { g.s = g.s.map(([id, ic, n, d, i, o]) => ({ id, ic, n, d, i, o, g })); });
  const ALL = G.flatMap(g => g.s), byId = id => ALL.find(x => x.id === id);
  // the workflow it adds to: a trigger and two steps to start with
  const START = [{ ic:'bolt', n:'When a ticket arrives', l:'Trigger', col:'var(--py)' }, byId('classify'), byId('db')];
  const root = $('.slb', r), P = $('.slb-p', r), q = $('.slb-in', r), xB = $('.slb-x', r), list = $('.slb-list', r), ct = $('.slb-ct', r), dock = $('.slb-dock', r);
  const pv = $('.slb-pv', r), descs = $('.slb-d', r), live = $('.slb-live', r), flow = $('.slb-flow', r), fl = $('.slb-fl', r), fn = $('.slb-fn', r);
  const uid = Math.random().toString(36).slice(2, 7);
  const say = t => { live.textContent = t; };
  const esc = s => s.replace(/[&<>"]/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' })[ch]);
  const tile = (ic, col, fg) => `<span class="ic" style="color:${fg || col};background:color-mix(in srgb,${col} 14%,transparent)">${I(ic, 'xs')}</span>`;
  // each step's description, for its row's aria-describedby
  descs.innerHTML = ALL.map(st => `<span id="slb-d-${st.id}-${uid}">${st.d}</span>`).join('');
  /* ---------- the list: a group per kind of step, each folding on its own; the search narrows the names (or a whole group
     by its name) and opens any folded group it finds something in ---------- */
  const shut = new Set();
  const markName = (n, v) => { const i = v ? n.toLowerCase().indexOf(v) : -1; return i < 0 ? esc(n) : esc(n.slice(0, i)) + '<mark>' + esc(n.slice(i, i + v.length)) + '</mark>' + esc(n.slice(i + v.length)); };
  function paint(){
    const v = q.value.trim().toLowerCase(); xB.hidden = !q.value; let n = 0;
    list.innerHTML = G.map(g => {
      const hs = g.s.filter(st => !v || st.n.toLowerCase().includes(v) || g.l.toLowerCase().startsWith(v)); if (!hs.length) return '';
      if (v) shut.delete(g.id);
      n += hs.length; const open = !shut.has(g.id), fid = `slb-g-${g.id}-${uid}`;
      return `<div class="slb-g" data-g="${g.id}"><button class="slb-gb" tabindex="-1" aria-expanded="${open}" aria-controls="${fid}">${I('chev-d', 'xs')}<span>${g.l}</span><span class="n num">${hs.length}</span></button>`
        + `<div class="fold${open ? '' : ' shut'}" id="${fid}"><div><ul class="slb-ul">${hs.map(st => `<li><button class="slb-s" tabindex="-1" data-id="${st.id}" draggable="true" aria-describedby="slb-d-${st.id}-${uid}">${tile(st.ic, g.col, g.fg)}<span class="t">${markName(st.n, v)}</span><span class="ad" aria-hidden="true">${I('plus', 'xs')}</span></button></li>`).join('')}</ul></div></div></div>`;
    }).join('') || `<div class="slb-e"><b>No steps match “${esc(q.value.trim())}”</b><span>Try another word, or clear the search.</span><button class="pill ghost sm slb-ec">Clear search</button></div>`;
    ct.textContent = v ? `${n} of ${ALL.length}` : `${ALL.length} steps`;
    if (v) say(n ? `${n} ${n === 1 ? 'step' : 'steps'} found` : 'No steps found');
    const it = items(); rove(it.find(b => b.matches('.slb-s')) || it[0], false);
    hov = null; sync();
  }
  // the list is one tab stop: the up and down arrows move through the group headers and steps that show
  const items = () => $$('.slb-gb,.slb-s,.slb-ec', list).filter(b => !b.closest('.fold.shut'));
  function rove(to){ items().forEach(b => { b.tabIndex = b === to ? 0 : -1; }); }
  const keep = b => { const lr = list.getBoundingClientRect(), br = b.getBoundingClientRect(); if (br.top < lr.top + 4) list.scrollTop -= lr.top + 4 - br.top; else if (br.bottom > lr.bottom - 4) list.scrollTop += br.bottom - lr.bottom + 4; };
  const go = b => { rove(b); b.focus({ preventScroll:true }); keep(b); };
  function toggle(gb){
    const g = gb.closest('.slb-g'), open = gb.getAttribute('aria-expanded') !== 'true';
    gb.setAttribute('aria-expanded', open); $('.fold', g).classList.toggle('shut', !open); open ? shut.delete(g.dataset.g) : shut.add(g.dataset.g);
    rove(gb);
  }
  // only the person's own Clear brings the focus back to the field; the demo's leaves it where it is
  function clear(){ const back = root.contains(document.activeElement); q.value = ''; paint(); if (back) q.focus({ preventScroll:true }); say('Search cleared'); }
  xB.onclick = clear;
  c.on(q, 'input', paint);
  c.on(q, 'keydown', e => {
    const first = () => items().find(b => b.matches('.slb-s')) || items()[0];
    if (e.key === 'ArrowDown'){ const f = first(); if (f){ e.preventDefault(); go(f); } }
    else if (e.key === 'Enter' && q.value.trim()){ const f = $('.slb-s', list); if (f){ e.preventDefault(); add(f.dataset.id, 'keyboard', f); } }
    else if (e.key === 'Escape' && q.value){ e.preventDefault(); e.stopPropagation(); clear(); }
  });
  c.on(list, 'click', e => {
    const b = e.target.closest('button'); if (!b) return;
    if (b.matches('.slb-gb')) toggle(b); else if (b.matches('.slb-s')) add(b.dataset.id, e.detail ? 'click' : 'keyboard', b); else if (b.matches('.slb-ec')) clear();
  });
  c.on(list, 'keydown', e => {
    const all = items(), i = all.indexOf(document.activeElement); if (i < 0) return;
    const k = e.key, b = all[i];
    if (k === 'ArrowDown' || k === 'ArrowUp'){ e.preventDefault(); const j = i + (k === 'ArrowDown' ? 1 : -1); if (j < 0) q.focus({ preventScroll:true }); else if (j < all.length) go(all[j]); }
    else if (k === 'Home' || k === 'End'){ e.preventDefault(); go(all[k === 'Home' ? 0 : all.length - 1]); }
    else if (b.matches('.slb-gb') && (k === 'ArrowLeft' || k === 'ArrowRight')){ e.preventDefault(); if ((k === 'ArrowRight') !== (b.getAttribute('aria-expanded') === 'true')) toggle(b); }
    else if (b.matches('.slb-s') && k === 'ArrowLeft'){ e.preventDefault(); go($('.slb-gb', b.closest('.slb-g'))); }
    else if (k === 'Escape' && q.value){ e.preventDefault(); clear(); }
    // typing anywhere in the list goes on into the search
    else if (k === 'Backspace' && q.value){ e.preventDefault(); q.value = q.value.slice(0, -1); q.focus({ preventScroll:true }); paint(); }
    else if (k.length === 1 && k !== ' ' && !e.ctrlKey && !e.metaKey && !e.altKey){ e.preventDefault(); q.value += k; q.focus({ preventScroll:true }); paint(); }
  });
  /* ---------- the preview: what the hovered step does, or the focused one's, beside the panel level with its row. It waits a
     moment for the first, then follows straight away from row to row ---------- */
  let hov = null, pvFor = null, tT = 0; c.offs.push(() => clearTimeout(tT));
  const narrow = () => root.clientWidth < 560;
  const rest = () => { dock.innerHTML = `<span class="hint">${matchMedia('(hover:hover)').matches ? 'Hover or focus a step to see what it does' : 'Tap a step to add it to the workflow'}</span>`; };
  function show(b){
    const st = byId(b.dataset.id); if (!st) return;
    $$('.slb-s.on', list).forEach(x => x !== b && x.classList.remove('on')); b.classList.add('on'); pvFor = b;
    if (narrow()){ dock.innerHTML = `<div class="slb-ph">${tile(st.ic, st.g.col, st.g.fg)}<div><b>${st.n}</b><span>${st.g.l}</span></div></div><p class="slb-pd">${st.d}</p>`; return; }
    const was = pv.classList.contains('show');
    pv.classList.toggle('jump', !was);
    pv.innerHTML = `<div class="slb-ph">${tile(st.ic, st.g.col, st.g.fg)}<div><b>${st.n}</b><span>${st.g.l}</span></div></div><p class="slb-pd">${st.d}</p><dl class="slb-io"><dt>Takes</dt><dd>${st.i}</dd><dt>Gives</dt><dd>${st.o}</dd></dl><p class="slb-pf">Press Enter or click to add it, or drag it into the workflow</p>`;
    const rr = root.getBoundingClientRect(), br = b.getBoundingClientRect(), pr = P.getBoundingClientRect();
    pv.style.left = Math.round(pr.right - rr.left + 8) + 'px';
    pv.style.top = Math.round(Math.max(0, Math.min(root.clientHeight - pv.offsetHeight, br.top - rr.top - 8))) + 'px';
    pv.classList.add('show');
  }
  function hide(){ pv.classList.remove('show'); $$('.slb-s.on', list).forEach(x => x.classList.remove('on')); pvFor = null; rest(); }
  const target = () => hov && hov.isConnected ? hov : (list.contains(document.activeElement) && document.activeElement.matches('.slb-s') ? document.activeElement : null);
  const sync = () => { const t = target(); t ? show(t) : hide(); };
  c.on(list, 'pointerover', e => {
    if (e.pointerType !== 'mouse') return; const b = e.target.closest('.slb-s');
    if (b === hov) return; hov = b; clearTimeout(tT); tT = setTimeout(sync, b ? (pvFor ? 0 : 280) : 120);
  });
  c.on(list, 'pointerleave', () => { hov = null; clearTimeout(tT); tT = setTimeout(sync, 120); });
  c.on(list, 'focusin', () => { clearTimeout(tT); sync(); });
  c.on(list, 'focusout', e => { if (!list.contains(e.relatedTarget)){ clearTimeout(tT); tT = setTimeout(sync, 0); } });
  c.on(list, 'scroll', () => { if (pvFor && !narrow()) show(pvFor); }, { passive:true });
  /* ---------- adding: Enter, a click, or a drop on the workflow. The workflow shows the new step, the row ticks, and the
     component fires step-add with the step's id, name, group and how it was added ---------- */
  const flowItem = x => `<li class="slb-fs"><span class="slb-cn" aria-hidden="true"></span><span class="ic" style="color:${x.g ? x.g.fg || x.g.col : x.col}">${I(x.ic, 'xs')}</span><span class="t"><b>${x.n}</b><span>${x.g ? x.g.l : x.l}</span></span></li>`;
  fl.innerHTML = START.map(flowItem).join('');
  const count = () => { const n = fl.children.length; fn.textContent = `${n} steps`; return n; };
  count();
  function add(id, via, b){
    const st = byId(id); if (!st) return;
    const li = html(flowItem(st)); li.classList.add('in'); fl.appendChild(li);
    fl.scrollTo({ top:fl.scrollHeight, behavior:REDUCE ? 'auto' : 'smooth' });
    const n = count();
    if (b && b.isConnected){ b.classList.add('added'); $('.ad', b).innerHTML = I('check', 'xs');
      c.later(1400, () => { if (b.isConnected){ b.classList.remove('added'); $('.ad', b).innerHTML = I('plus', 'xs'); } }); }
    say(`Added ${st.n}. ${n} steps in Support triage`);
    // a hovered step's preview goes once it is in (a focused one's stays); on a narrow screen the panel's foot says it
    // was added, for a moment
    hov = null; sync();
    if (narrow()){ dock.innerHTML = `<div class="slb-ph slb-ok">${tile('check', 'var(--ok)')}<div><b>Added ${st.n}</b><span>${n} steps in Support triage</span></div></div>`;
      c.later(2400, () => { if ($('.slb-ok', dock)) sync(); }); }
    root.dispatchEvent(new CustomEvent('step-add', { bubbles:true, detail:{ id:st.id, name:st.n, group:st.g.id, via } }));
  }
  // a step dragged out of the list drops into the workflow
  const MIME = 'application/x-designme-step';
  c.on(list, 'dragstart', e => {
